export async function run(job: Job) {
  for (let attempt = 0; attempt < clientConfig.maxRetries; attempt++) {
    try {
      return await send(job)
    } catch {
      await sleep(clientConfig.backoffMs * 2 ** attempt)
    }
  }
}
